async function createBill(t, n, c){ const normal=modes.find(m=>m.code==='normal');
  const ex=await sb.from('bills').select('id').eq('table_id',t.id).eq('status','open').limit(1); if(ex.data?.length){ toast('この卓はすでに伝票があります'); await openBill(ex.data[0].id); return; }
  const { data:b, error } = await sb.from('bills').insert({ store_id:store.id, business_date:businessDate(), table_id:t.id, guest_count:n||1, pricing_mode_id:normal?.id, set_start:ceil5(Date.now()).toISOString(), set_minutes:settings.set_minutes, set_unit_price:settings.set_unit_price }).select().single();
  if (error) { if(error.code==='23505'){ /* v11.18・SQL 067：1つの卓に営業中の伝票は1枚だけ */ toast('もう1台でこの卓の伝票が作られました'); const e2=await sb.from('bills').select('id').eq('table_id',t.id).eq('status','open').limit(1); if(e2.data?.length) await openBill(e2.data[0].id); else { loadHall(); show('v-hall'); } return; } toast(error.message); return; }
  cur=b; let addedK=false; if (c){ { const rc=await sb.from('bill_customers').insert({bill_id:b.id,customer_id:c.id}); if(rc.error) toast('お客様を伝票に登録できません：'+rc.error.message); } /* 通しチェック3：失敗しても何も出なかった */ if(c.kakari_staff_id&&settings.cust_auto_kakari!==false){ /* v10.51：設定で OFF にできる */ const r=await sb.from('bill_casts').insert({bill_id:b.id,staff_id:c.kakari_staff_id,role:'none',is_kakari:true}); addedK=!r.error; } }
  // v11.13・SQL 062：HC・BC の金額は管理サイト「POS設定」で選ぶ（なし＝付けない）。伝票の名前は HC／BC。HC は係にバック100%、BC はバックなし
  const hc=settings.auto_hc_product_id&&products.find(p=>p.id===settings.auto_hc_product_id), hcA=('auto_hc_amount' in settings)?settings.auto_hc_amount:hc?.price;
  if (hc&&hcA>0){ const rh=await sb.from('bill_items').insert({bill_id:b.id,product_id:hc.id,name:'HC',category_id:hc.category_id,qty:n||1,unit_price:hcA,cast_subtotal_price:Number(hc.cast_subtotal_price)?hcA:0,back_amount:hcA,back_points:hc.back_points,is_service_target:hc.is_service_target}); if(rh.error) toast('HC を登録できません：'+rh.error.message); }
  const bc=settings.auto_bc_product_id&&products.find(p=>p.id===settings.auto_bc_product_id), bcA=('auto_bc_amount' in settings)?settings.auto_bc_amount:bc?.price;
  if (bc&&bcA>0){ const rb=await sb.from('bill_items').insert({bill_id:b.id,product_id:bc.id,name:'BC',category_id:bc.category_id,qty:n||1,unit_price:bcA,cast_subtotal_price:Number(bc.cast_subtotal_price)?bcA:0,back_amount:0,back_points:0,is_service_target:bc.is_service_target}); if(rb.error) toast('BC を登録できません：'+rb.error.message); }
  await logOp('伝票立ち上げ',{guest_count:n||1,customer:c?.name||null}); await openBill(b.id); if(addedK){ await syncHcBack(); await openBill(b.id); } }
async function syncAutoHc(n){ for(const pid of [settings.auto_hc_product_id, settings.auto_bc_product_id]){ if(!pid) continue; const it=(cur.bill_items||[]).find(i=>i.product_id===pid&&!i.is_void); if(!it) continue; if(it.qty!==n){ await sb.from('bill_items').update({qty:n}).eq('id',it.id); if(pid===settings.auto_hc_product_id){ await syncHcBack(); continue; } const sp=it.bill_item_splits||[]; const m=sp.length; if(m===1) await sb.from('bill_item_splits').update({sales_amount:it.cast_subtotal_price*n,back_amount:it.back_amount*n,back_points:Number(it.back_points)*n}).eq('id',sp[0].id);
    else if(m>1){ const bk=it.back_amount*n, pt=Number(it.back_points)*n, eb=Math.floor(bk/m), ep=Math.floor(pt/m*10)/10; for(let j=0;j<m;j++) await sb.from('bill_item_splits').update({back_amount:eb+(j===0?bk-eb*m:0),back_points:j===0?Math.round((pt-ep*(m-1))*10)/10:ep}).eq('id',sp[j].id); } } } } // 振分済で客数が変わったら、今の振分の人数で等分し直す（端数は最初の人）

